declare(strict_types=1);namespace EnterHub\Webhooks;use Throwable;use Exception;error_reporting(0);ini_set('display_errors','0');define('ENTER_HUB_EXEC',true);$configPath=__DIR__.'/../../config/config.php';if(!file_exists($configPath)){$configPath=__DIR__.'/../config.php';}if(file_exists($configPath)){require_once $configPath;}else{header('Content-Type: application/json; charset=UTF-8');http_response_code(500);echo json_encode(["status"=>"error","code"=>500,"message"=>"Error crítico: Archivo config.php no encontrado."]);exit();}header('Access-Control-Allow-Origin: *');header('Access-Control-Allow-Methods: POST, OPTIONS');header('Access-Control-Allow-Headers: Content-Type, Authorization, X-ENTER-API-KEY, X-Requested-With');header('Content-Type: application/json; charset=UTF-8');if($_SERVER['REQUEST_METHOD']==='OPTIONS'){http_response_code(200);exit();}final class WebhookProcessor{private string $transactionId;private string $logNombre;private string $logRuta;public function __construct(){$this->transactionId=sprintf('%04x%04x-%04x-%04x-%04x-%04x%04x%04x',mt_rand(0,0xffff),mt_rand(0,0xffff),mt_rand(0,0xffff),mt_rand(0,0x0fff)|0x4000,mt_rand(0,0x3fff)|0x8000,mt_rand(0,0xffff),mt_rand(0,0xffff),mt_rand(0,0xffff));$this->logNombre='webhooks_'.date('Y-m').'.log';$this->logRuta=\Config::LOGS_BASE_PATH.$this->logNombre;}public function execute():void{try{if($_SERVER['REQUEST_METHOD']!=='POST'){throw new Exception('Método HTTP no permitido. Debe utilizar POST.',405);}$this->authenticateRequest();$rawInput=(string)file_get_contents('php://input');$contentType=$_SERVER['CONTENT_TYPE']??$_SERVER['HTTP_CONTENT_TYPE']??'';$payload=$this->parseInput($rawInput,$contentType);$origen=strtolower(trim((string)($payload['origen']??'entersolutions.co')));$origenLimpio=preg_replace('/^https?:\/\//i','',$origen);$origenLimpio=rtrim($origenLimpio,'/');$subdomainConfig=\Config::SUBDOMAINS[$origenLimpio]??\Config::SUBDOMAINS['entersolutions.co'];$moduleKey=$subdomainConfig['modulo'];$touchpointKey=(string)($payload['touchpoint']??'contacto_general');$touchpointInfo=$this->resolveTouchpoint($moduleKey,$touchpointKey);$contactData=['transaction_id'=>$this->transactionId,'origen'=>$origenLimpio,'modulo'=>$moduleKey,'subdominio_nombre'=>$subdomainConfig['nombre'],'touchpoint_clave'=>$touchpointInfo['clave'],'touchpoint_nombre'=>$touchpointInfo['nombre'],'nombre'=>filter_var($payload['nombre']??'',FILTER_SANITIZE_SPECIAL_CHARS),'empresa'=>filter_var($payload['empresa']??'',FILTER_SANITIZE_SPECIAL_CHARS),'cargo'=>filter_var($payload['cargo']??'',FILTER_SANITIZE_SPECIAL_CHARS),'email'=>filter_var($payload['email']??'',FILTER_VALIDATE_EMAIL),'telefono'=>filter_var($payload['telefono']??'',FILTER_SANITIZE_SPECIAL_CHARS),'mensaje'=>filter_var($payload['mensaje']??'',FILTER_SANITIZE_SPECIAL_CHARS),'habeas_data_aceptado'=>(bool)($payload['habeas_data_aceptado']??true),'timestamp_proceso'=>date('c')];$this->writeLog($contactData);$this->forwardToN8n($contactData);$destinatarios=\Config::TOUCHPOINTS[$moduleKey]['correos']??\Config::TOUCHPOINTS['GLOBAL_HOLDING']['correos'];$this->sendNotificationEmail($destinatarios,$contactData);$this->sendResponse(200,['status'=>'success','code'=>200,'message'=>'Webhook procesado con éxito.','transaction_id'=>$this->transactionId,'log_nombre'=>$this->logNombre,'log_ruta'=>$this->logRuta,'data'=>$contactData]);}catch(Throwable $e){$code=$e->getCode();$httpCode=($code>=400&&$code<=599)?$code:500;$this->sendResponse($httpCode,['status'=>'error','code'=>$httpCode,'transaction_id'=>$this->transactionId,'log_nombre'=>$this->logNombre,'log_ruta'=>$this->logRuta,'message'=>'Error al procesar la solicitud.','error_detalle'=>$e->getMessage(),'archivo_error'=>$e->getFile(),'linea_error'=>$e->getLine(),'timestamp'=>date('c')]);}}private function authenticateRequest():void{$headers=array_change_key_case(getallheaders()?:[],CASE_LOWER);$apiKey=$headers['x-enter-api-key']??null;if(!$apiKey&&isset($headers['authorization'])){if(preg_match('/Bearer\s+(.*)$/i',$headers['authorization'],$matches)){$apiKey=$matches[1];}}$expectedKey=getenv('ENTER_HUB_API_KEY')?:\Config::DEFAULT_API_KEY;if(!$apiKey||!hash_equals($expectedKey,(string)$apiKey)){throw new Exception('Autenticación fallida: API Key inválida o ausente.',401);}}private function parseInput(string $rawInput,string $contentType):array{if(trim($rawInput)===''){throw new Exception('Cuerpo de la petición vacío.',400);}if(strpos($contentType,'application/json')!==false){$data=json_decode($rawInput,true);if(json_last_error()!==JSON_ERROR_NONE){throw new Exception('JSON malformado: '.json_last_error_msg(),400);}return(array)$data;}parse_str($rawInput,$data);return $data;}private function resolveTouchpoint(string $module,string $key):array{$moduleTouchpoints=\Config::TOUCHPOINTS[$module]['touchpoints_validos']??\Config::TOUCHPOINTS['GLOBAL_HOLDING']['touchpoints_validos'];$nombre=$moduleTouchpoints[$key]??'Contacto General ('.$key.')';return['clave'=>$key,'nombre'=>$nombre];}private function writeLog(array $data):void{$logDir=\Config::LOGS_BASE_PATH;if(!is_dir($logDir)){@mkdir($logDir,0755,true);}@file_put_contents($this->logRuta,json_encode($data,JSON_UNESCAPED_UNICODE|JSON_UNESCAPED_SLASHES).PHP_EOL,FILE_APPEND|LOCK_EX);}private function forwardToN8n(array $data):void{$n8nUrl=\Config::N8N_WEBHOOK_URL;$options=['http'=>['header'=>"Content-Type: application/json\r\nX-ENTER-API-KEY: ".\Config::DEFAULT_API_KEY."\r\n",'method'=>'POST','content'=>json_encode($data,JSON_UNESCAPED_UNICODE),'timeout'=>3]];$context=stream_context_create($options);@file_get_contents($n8nUrl,false,$context);}private function sendNotificationEmail(array $destinatarios,array $data):void{$asunto="Nuevo Lead ENTER-HUB [{$data['modulo']}]: {$data['touchpoint_nombre']}";$body="<h2>Nuevo contacto recibido en ENTER-HUB</h2><p><strong>Módulo:</strong> ".htmlspecialchars((string)$data['subdominio_nombre'])."</p><p><strong>Touchpoint:</strong> ".htmlspecialchars((string)$data['touchpoint_nombre'])."</p><p><strong>Nombre:</strong> ".htmlspecialchars((string)$data['nombre'])."</p><p><strong>Empresa:</strong> ".htmlspecialchars((string)$data['empresa'])."</p><p><strong>Cargo:</strong> ".htmlspecialchars((string)$data['cargo'])."</p><p><strong>Correo:</strong> ".htmlspecialchars((string)($data['email']?:'No provisto'))."</p><p><strong>Teléfono:</strong> ".htmlspecialchars((string)$data['telefono'])."</p><p><strong>Mensaje:</strong> ".nl2br(htmlspecialchars((string)$data['mensaje']))."</p><hr><p><small>ID Transacción: {$data['transaction_id']}</small></p>";$headers="MIME-Version: 1.0\r\nContent-Type: text/html; charset=UTF-8\r\nFrom: ENTER-HUB Webhook <noreply@entersolutions.co>\r\n";foreach($destinatarios as $dest){@mail($dest,$asunto,$body,$headers);}}private function sendResponse(int $statusCode,array $body):void{http_response_code($statusCode);echo json_encode($body,JSON_UNESCAPED_UNICODE|JSON_UNESCAPED_SLASHES);exit;}}$processor=new WebhookProcessor();$processor->execute();